//
//  Test helpers for the chain bridges. The JS bundles are read from the repository's `js/` directory (a simulator
//  process can read host paths), located from this file's #filePath; `OWNBIT_JS_DIR` (or `TEST_RUNNER_OWNBIT_JS_DIR`
//  passed through xcodebuild) overrides it. Tests skip with a clear message when the files are not there yet.

import Foundation
import XCTest
@testable import OwnbitCore

enum ChainsTestSupport {

    /// …/ownbit-app-50/js
    static let jsDirectory: URL = {
        if let override = ProcessInfo.processInfo.environment["OWNBIT_JS_DIR"], !override.isEmpty {
            return URL(fileURLWithPath: override, isDirectory: true)
        }
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { // Chains → OwnbitCoreTests → Tests → iOS → repository root
            url.deleteLastPathComponent()
        }
        return url.appendingPathComponent("js", isDirectory: true)
    }()

    /// Points `JSBridge.resourceBundle` at the repository's js/ and checks that `files` (paths inside js/) exist.
    static func useRepositoryJS(_ files: [String], file: StaticString = #filePath, line: UInt = #line) throws {
        let missing = files.filter { !FileManager.default.fileExists(atPath: jsDirectory.appendingPathComponent($0).path) }
        guard missing.isEmpty else {
            throw XCTSkip("js/ is not populated yet (missing \(missing.joined(separator: ", ")) in \(jsDirectory.path))")
        }
        guard let bundle = Bundle(path: jsDirectory.path) else {
            throw XCTSkip("cannot open \(jsDirectory.path) as a bundle")
        }
        JSBridge.resourceBundle = bundle
    }

    static let bitcoinJS = "bitcoinjs-lib-bridge/bitcoinjs-lib-app.js"
    static let bitcoinPage = "bitcoinjs-lib-bridge/btc_index.html"
    static let wordlist = "bitcoinjs-lib-bridge/mnemonic_words.txt"
    static let taprootPage = "btctaprootjs-lib-bridge/btc_taproot_index.html"
    static let taprootJS = "btctaprootjs-lib-bridge/btctaproot-lib-app.js"
    static let ethereumJS = "ethereumjs-lib-bridge/ethereumjs-lib-app.min.js"
    static let tronPage = "tronjs-lib-bridge/trx_index.html"
    static let tronJS = "tronjs-lib-bridge/trxjs-lib-app.js"
    static let solanaPage = "soljs-lib-bridge/sol_index.html"
    static let solanaJS = "soljs-lib-bridge/soljs-lib-app.js"
    static let rippleJS = "ripplejs-lib-bridge/ripplejs-lib-app.min.js"
    static let stellarJS = "stellarjs-lib-bridge/stellarjs-lib-app.min.js"

    /// Runs one bridge call and waits for its first completion, failing after `timeout` seconds.
    static func call<T>(timeout: TimeInterval = 300, _ start: @escaping (_ done: @escaping (Result<T, Error>) -> Void) -> Void) async throws -> T {
        let once = Once<T>()
        return try await withCheckedThrowingContinuation { continuation in
            once.continuation = continuation
            DispatchQueue.main.asyncAfter(deadline: .now() + timeout) {
                once.finish(.failure(ChainsTestError.timeout))
            }
            DispatchQueue.main.async {
                start { once.finish($0) }
            }
        }
    }

    private final class Once<T>: @unchecked Sendable {
        var continuation: CheckedContinuation<T, Error>?
        private let lock = NSLock()

        func finish(_ result: Result<T, Error>) {
            lock.lock()
            let c = continuation
            continuation = nil
            lock.unlock()
            c?.resume(with: result)
        }
    }
}

enum ChainsTestError: Error {
    case timeout
}

